## Code Example

```typescript
export interface ICommand {
  name: string
  execute(ctx: ICommandContext, args?: any): Promise<any>
}

export interface ICommandContext {
  log(msg: string): void
}

export interface ICommandFactory {
  register(name: string, creator: () => ICommand): void
  unregister(name: string): void
  get(name: string): Promise<ICommand | null>
}

export class CommandRegistry implements ICommandFactory {
  private map = new Map<string, () => ICommand>()

  register(name: string, creator: () => ICommand): void {
    this.map.set(name, creator)
  }

  unregister(name: string): void {
    this.map.delete(name)
  }

  async get(name: string): Promise<ICommand | null> {
    const creator = this.map.get(name)
    if (!creator) return null
    // instantiate on demand to keep per-call isolation
    return creator()
  }
}

// Usage snippet
// dynamic plugin loader
async function loadPlugin(path: string, registry: ICommandFactory) {
  const mod = await import(path)
  if (typeof mod.registerCommand === 'function') {
    mod.registerCommand(registry)
  }
}
```

